preConditionHook:
// THE BREAK OF THE WEDGE'S OTHER SIDE. Three pushes DOWN are in place and the
// close clears the most recent confirmed swing high -- the level the wedge's
// opposite line runs through -- so the pattern breaks upward (long); the short
// is the mirror, three pushes up and a close below the most recent swing low.
//
// Kept apart from ThreePushReversalEntry deliberately: a break of a pivot
// LEVEL and a close beyond the PRIOR BAR's extreme are different bars, often
// many bars apart. This is V00-62's order type -- beyond the breakout of the
// third push's opposite trend line -- mechanized as the pivot itself rather
// than as a projected line, so no TLValue anchor pair is needed.
//
// THE -1 SENTINEL matters here: the scan leaves hiPx1 at -1 when no pivot lies
// in the window, and -1 as a PRICE sits under every real price, so a close
// would sail over it. nHiPiv >= 1 is that guard.
//
// Pivot scan as in ThreePushPattern, inlined (rules here never reference each
// other; the register lists Occurrence 3+ as unmeasured, so the third push is
// found by hand). MEASURED (EL_Swing_Probe.txt / el_swing_output1.txt, @ES 60
// min): the pivot bar is AT OR ABOVE the swingStrength OLDER bars and STRICTLY
// ABOVE the swingStrength NEWER bars -- bars-ago indexing, so the newer bars
// are the smaller k and take el_gt / el_lt, the older el_ge / el_le;
// confirmation lag exactly swingStrength bars; candidate offsets
// swingStrength .. lookbackBars - 1 with the neighbourhood reaching
// swingStrength bars past the window, so the deepest bar touched is
// lookbackBars - 1 + swingStrength; newest-first recording reproduces
// Occurrence 1, 2, 3. No early break, matching the twin.
// Scratch below is declared in localVariables, not at hook scope: the
// generator only prefixes declared locals, so a hook-scope declaration
// is a redefinition when this rule is placed twice in one strategy.
// Every one is fully assigned each bar before it is read.
pivStrength = (int)swingStrength;
pivWindow = (int)lookbackBars;
nHiPiv = 0;
nLoPiv = 0;
hiPx1 = -1.0;
hiPx2 = -1.0;
hiPx3 = -1.0;
loPx1 = -1.0;
loPx2 = -1.0;
loPx3 = -1.0;
for (int j = pivStrength; j <= pivWindow - 1; ++j) {
    bool okHi = true;
    bool okLo = true;
    for (int k = j - pivStrength; k < j; ++k) {
        if (!el_gt(high[j], high[k])) okHi = false;
        if (!el_lt(low[j], low[k])) okLo = false;
    }
    for (int k = j + 1; k <= j + pivStrength; ++k) {
        if (!el_ge(high[j], high[k])) okHi = false;
        if (!el_le(low[j], low[k])) okLo = false;
    }
    if (okHi && nHiPiv < 3) {
        nHiPiv = nHiPiv + 1;
        if (nHiPiv == 1) hiPx1 = high[j];
        if (nHiPiv == 2) hiPx2 = high[j];
        if (nHiPiv == 3) hiPx3 = high[j];
    }
    if (okLo && nLoPiv < 3) {
        nLoPiv = nLoPiv + 1;
        if (nLoPiv == 1) loPx1 = low[j];
        if (nLoPiv == 2) loPx2 = low[j];
        if (nLoPiv == 3) loPx3 = low[j];
    }
}
patUp = (nHiPiv == 3) && el_gt(hiPx1, hiPx2) && el_gt(hiPx2, hiPx3);
patDn = (nLoPiv == 3) && el_lt(loPx1, loPx2) && el_lt(loPx2, loPx3);
haveHiPiv = (nHiPiv >= 1);
haveLoPiv = (nLoPiv >= 1);
